        new Main().executeProgram();
    }

    FastReader reader = new FastReader();
    PrintWriter writer = new PrintWriter(System.out);

    void executeProgram() {
        processData();
        writer.flush();
    }

    long MOD = 1000000007;

    long getGCD(long a, long b) {
        while (a != 0) {
            long temp = a;
            a = b % a;
            b = temp;
